package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// jsonThemeData represents the JSON structure for theme configuration
type jsonThemeData struct {
	Colors      map[string]string `json:"Colors"`
	ColorsDark  map[string]string `json:"Colors-dark"`
	ColorsLight map[string]string `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string `json:"Fonts"`
	Icons       map[string]string `json:"Icons"`
}

// jsonTheme wraps the default theme and overrides values from JSON
type jsonTheme struct {
	base fyne.Theme
	data *jsonThemeData
}

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var themeData jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&themeData); err != nil {
		return DefaultTheme(), err
	}

	return &jsonTheme{
		base: DefaultTheme(),
		data: &themeData,
	}, nil
}

// Color returns the color for the given name and variant, checking JSON overrides first
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	colorName := string(name)

	// Check variant-specific colors first
	var hexColor string
	var found bool

	if variant == fyne.VariantDark && t.data.ColorsDark != nil {
		hexColor, found = t.data.ColorsDark[colorName]
	} else if variant == fyne.VariantLight && t.data.ColorsLight != nil {
		hexColor, found = t.data.ColorsLight[colorName]
	}

	// Fall back to generic Colors if not found in variant-specific
	if !found && t.data.Colors != nil {
		hexColor, found = t.data.Colors[colorName]
	}

	if found {
		if c, err := parseHexColor(hexColor); err == nil {
			return c
		}
	}

	// Fall back to base theme
	return t.base.Color(name, variant)
}

// Font returns the font for the given text style, checking JSON overrides first
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if t.data.Fonts != nil {
		var fontName string
		if style.Monospace {
			fontName = "monospace"
		} else if style.Bold && style.Italic {
			fontName = "boldItalic"
		} else if style.Bold {
			fontName = "bold"
		} else if style.Italic {
			fontName = "italic"
		} else {
			fontName = "regular"
		}

		if uriStr, found := t.data.Fonts[fontName]; found {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				if res, err := storage.LoadResourceFromURI(uri); err == nil {
					return res
				}
			}
		}
	}

	// Fall back to base theme
	return t.base.Font(style)
}

// Icon returns the icon for the given name, checking JSON overrides first
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if t.data.Icons != nil {
		iconName := string(name)
		if uriStr, found := t.data.Icons[iconName]; found {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				if res, err := storage.LoadResourceFromURI(uri); err == nil {
					return res
				}
			}
		}
	}

	// Fall back to base theme
	return t.base.Icon(name)
}

// Size returns the size for the given name, checking JSON overrides first
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.data.Sizes != nil {
		sizeName := string(name)
		if size, found := t.data.Sizes[sizeName]; found {
			return size
		}
	}

	// Fall back to base theme
	return t.base.Size(name)
}

// parseHexColor parses hex color strings in various formats:
// - 3 digits: "abc" -> 0xaa 0xbb 0xcc 0xff
// - 4 digits: "abcd" -> 0xaa 0xbb 0xcc 0xdd
// - 6 digits: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
// - 8 digits: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
// All formats support optional "#" prefix
func parseHexColor(hexStr string) (color.Color, error) {
	// Remove # prefix if present
	hexStr = strings.TrimPrefix(hexStr, "#")

	var r, g, b, a uint8

	switch len(hexStr) {
	case 3:
		// RGB: each digit is duplicated (e.g., "abc" -> "aabbcc")
		vals, err := parseHexDigits(hexStr, 1)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[0])
		g = uint8(vals[1]<<4 | vals[1])
		b = uint8(vals[2]<<4 | vals[2])
		a = 0xff

	case 4:
		// RGBA: each digit is duplicated (e.g., "abcd" -> "aabbccdd")
		vals, err := parseHexDigits(hexStr, 1)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[0])
		g = uint8(vals[1]<<4 | vals[1])
		b = uint8(vals[2]<<4 | vals[2])
		a = uint8(vals[3]<<4 | vals[3])

	case 6:
		// RRGGBB
		vals, err := parseHexDigits(hexStr, 2)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[1])
		g = uint8(vals[2]<<4 | vals[3])
		b = uint8(vals[4]<<4 | vals[5])
		a = 0xff

	case 8:
		// RRGGBBAA
		vals, err := parseHexDigits(hexStr, 2)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[1])
		g = uint8(vals[2]<<4 | vals[3])
		b = uint8(vals[4]<<4 | vals[5])
		a = uint8(vals[6]<<4 | vals[7])

	default:
		return color.NRGBA{}, fmt.Errorf("invalid hex color format: %s", hexStr)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigits parses hex digits from a string and returns their numeric values
func parseHexDigits(hexStr string, digitsPerComponent int) ([]uint8, error) {
	vals := make([]uint8, len(hexStr))
	for i, char := range hexStr {
		val, err := strconv.ParseUint(string(char), 16, 8)
		if err != nil {
			return nil, fmt.Errorf("invalid hex character: %c", char)
		}
		vals[i] = uint8(val)
	}
	return vals, nil
}

package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// jsonThemeData represents the JSON structure for theme configuration
type jsonThemeData struct {
	Colors      map[string]string `json:"Colors"`
	ColorsDark  map[string]string `json:"Colors-dark"`
	ColorsLight map[string]string `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string `json:"Fonts"`
	Icons       map[string]string `json:"Icons"`
}

// jsonTheme wraps the default theme and overrides values from JSON
type jsonTheme struct {
	base fyne.Theme
	data *jsonThemeData
}

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var themeData jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&themeData); err != nil {
		return DefaultTheme(), err
	}

	return &jsonTheme{
		base: DefaultTheme(),
		data: &themeData,
	}, nil
}

// Color returns the color for the given name and variant, checking JSON overrides first
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	colorName := string(name)

	// Check variant-specific colors first
	var hexColor string
	var found bool

	if variant == fyne.VariantDark && t.data.ColorsDark != nil {
		hexColor, found = t.data.ColorsDark[colorName]
	} else if variant == fyne.VariantLight && t.data.ColorsLight != nil {
		hexColor, found = t.data.ColorsLight[colorName]
	}

	// Fall back to generic Colors if not found in variant-specific
	if !found && t.data.Colors != nil {
		hexColor, found = t.data.Colors[colorName]
	}

	if found {
		if c, err := parseHexColor(hexColor); err == nil {
			return c
		}
	}

	// Fall back to base theme
	return t.base.Color(name, variant)
}

// Font returns the font for the given text style, checking JSON overrides first
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if t.data.Fonts != nil {
		var fontName string
		if style.Monospace {
			fontName = "monospace"
		} else if style.Bold && style.Italic {
			fontName = "boldItalic"
		} else if style.Bold {
			fontName = "bold"
		} else if style.Italic {
			fontName = "italic"
		} else {
			fontName = "regular"
		}

		if uriStr, found := t.data.Fonts[fontName]; found {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				if res, err := storage.LoadResourceFromURI(uri); err == nil {
					return res
				}
			}
		}
	}

	// Fall back to base theme
	return t.base.Font(style)
}

// Icon returns the icon for the given name, checking JSON overrides first
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if t.data.Icons != nil {
		iconName := string(name)
		if uriStr, found := t.data.Icons[iconName]; found {
			if uri, err := storage.ParseURI(uriStr); err == nil {
				if res, err := storage.LoadResourceFromURI(uri); err == nil {
					return res
				}
			}
		}
	}

	// Fall back to base theme
	return t.base.Icon(name)
}

// Size returns the size for the given name, checking JSON overrides first
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.data.Sizes != nil {
		sizeName := string(name)
		if size, found := t.data.Sizes[sizeName]; found {
			return size
		}
	}

	// Fall back to base theme
	return t.base.Size(name)
}

// parseHexColor parses hex color strings in various formats:
// - 3 digits: "abc" -> 0xaa 0xbb 0xcc 0xff
// - 4 digits: "abcd" -> 0xaa 0xbb 0xcc 0xdd
// - 6 digits: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
// - 8 digits: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
// All formats support optional "#" prefix
func parseHexColor(hexStr string) (color.Color, error) {
	// Remove # prefix if present
	hexStr = strings.TrimPrefix(hexStr, "#")

	var r, g, b, a uint8

	switch len(hexStr) {
	case 3:
		// RGB: each digit is duplicated (e.g., "abc" -> "aabbcc")
		vals, err := parseHexDigits(hexStr, 1)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[0])
		g = uint8(vals[1]<<4 | vals[1])
		b = uint8(vals[2]<<4 | vals[2])
		a = 0xff

	case 4:
		// RGBA: each digit is duplicated (e.g., "abcd" -> "aabbccdd")
		vals, err := parseHexDigits(hexStr, 1)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[0])
		g = uint8(vals[1]<<4 | vals[1])
		b = uint8(vals[2]<<4 | vals[2])
		a = uint8(vals[3]<<4 | vals[3])

	case 6:
		// RRGGBB
		vals, err := parseHexDigits(hexStr, 2)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[1])
		g = uint8(vals[2]<<4 | vals[3])
		b = uint8(vals[4]<<4 | vals[5])
		a = 0xff

	case 8:
		// RRGGBBAA
		vals, err := parseHexDigits(hexStr, 2)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8(vals[0]<<4 | vals[1])
		g = uint8(vals[2]<<4 | vals[3])
		b = uint8(vals[4]<<4 | vals[5])
		a = uint8(vals[6]<<4 | vals[7])

	default:
		return color.NRGBA{}, fmt.Errorf("invalid hex color format: %s", hexStr)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigits parses hex digits from a string and returns their numeric values
func parseHexDigits(hexStr string, digitsPerComponent int) ([]uint8, error) {
	vals := make([]uint8, len(hexStr))
	for i, char := range hexStr {
		val, err := strconv.ParseUint(string(char), 16, 8)
		if err != nil {
			return nil, fmt.Errorf("invalid hex character: %c", char)
		}
		vals[i] = uint8(val)
	}
	return vals, nil
}

package binding

import (
	"fmt"
)

// sprintfBinding is a String binding that formats multiple DataItems using fmt.Sprintf
type sprintfBinding struct {
	base
	format   string
	sources  []DataItem
	listener DataListener
}

// NewSprintf creates a String binding that formats multiple bindings using fmt.Sprintf.
// The format string follows the same rules as fmt.Sprintf.
// When any source binding changes, the formatted result is automatically updated.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:  format,
		sources: bindings,
	}

	// Create a listener that triggers when any source changes
	s.listener = NewDataListener(func() {
		s.trigger()
	})

	// Attach listener to all source bindings
	for _, source := range s.sources {
		source.AddListener(s.listener)
	}

	return s
}

// Get returns the formatted string
func (s *sprintfBinding) Get() (string, error) {
	values := make([]interface{}, len(s.sources))

	for i, source := range s.sources {
		var val interface{}
		var err error

		// Extract value based on type
		switch src := source.(type) {
		case String:
			val, err = src.Get()
		case Int:
			val, err = src.Get()
		case Float:
			val, err = src.Get()
		case Bool:
			val, err = src.Get()
		default:
			// For unknown types, try to get as String if possible
			if str, ok := source.(String); ok {
				val, err = str.Get()
			} else {
				return "", fmt.Errorf("unsupported binding type at index %d", i)
			}
		}

		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

// Set is not supported for sprintf bindings as they are computed from sources
func (s *sprintfBinding) Set(string) error {
	return fmt.Errorf("cannot set a sprintf binding")
}

// trigger notifies all listeners that the formatted value has changed
func (s *sprintfBinding) trigger() {
	s.lock.RLock()
	defer s.lock.RUnlock()

	for _, listener := range s.listeners {
		queueItem(listener.DataChanged)
	}
}

// stringFormatBinding wraps a String binding with a format string
type stringFormatBinding struct {
	base
	format   string
	source   String
	listener DataListener
}

// StringToStringWithFormat creates a String binding that formats another String binding.
// This is useful for adding prefixes, suffixes, or applying formatting to a single string value.
//
// Example:
//   username := binding.NewString()
//   greeting := binding.StringToStringWithFormat(username, "Hello, %s!")
//
// Since: 2.2
func StringToStringWithFormat(source String, format string) String {
	s := &stringFormatBinding{
		format: format,
		source: source,
	}

	// Create a listener that triggers when source changes
	s.listener = NewDataListener(func() {
		s.trigger()
	})

	source.AddListener(s.listener)

	return s
}

// Get returns the formatted string
func (s *stringFormatBinding) Get() (string, error) {
	val, err := s.source.Get()
	if err != nil {
		return "", err
	}
	return fmt.Sprintf(s.format, val), nil
}

// Set is not supported for format bindings as they are computed from source
func (s *stringFormatBinding) Set(string) error {
	return fmt.Errorf("cannot set a format binding")
}

// trigger notifies all listeners that the formatted value has changed
func (s *stringFormatBinding) trigger() {
	s.lock.RLock()
	defer s.lock.RUnlock()

	for _, listener := range s.listeners {
		queueItem(listener.DataChanged)
	}
}

