// pasteFromClipboard inserts text from the clipboard content,
// starting from the cursor position.
func (e *Entry) pasteFromClipboard(clipboard fyne.Clipboard) {
	if e.selecting {
		e.eraseSelection()
	}
	text := clipboard.Content()
	if !e.MultiLine {
		// format clipboard content to be compatible with single line entry
		text = strings.Replace(text, "\n", " ", -1)
	}

	// Validate pasted content if a validator is set
	// Since: 2.2
	if e.Validator != nil {
		provider := e.textProvider()
		pos := e.cursorTextPos()
		// Create a temporary copy to validate the result
		tempProvider := provider.copy()
		tempProvider.insertAt(pos, text)
		if err := e.Validator(tempProvider.String()); err != nil {
			// Validation failed, don't paste
			return
		}
	}

	provider := e.textProvider()
	runes := []rune(text)
	pos := e.cursorTextPos()
	provider.insertAt(pos, text)
	e.CursorRow, e.CursorColumn = e.rowColFromTextPos(pos + len(runes))

	e.updateText(provider.String())
	e.Refresh()
}

